#!/usr/bin/env node
/**
 * probe-cpu-attribution.js — where does the frame actually GO? (Mark 2026-07-16)
 *
 * WHY THIS EXISTS: Oni-Baba's architecture snapshot reported 32 fps (31ms/frame) with a
 * "total-frame render path 3.09ms" — a ~320fps render ceiling — while SILENCE sat at 100%
 * (i.e. the player was IDLE, gambling, no combat). So ~28ms of every frame was being burned
 * somewhere that is NOT the renderer, and her headline verdict ("excessive WebGL draw calls")
 * is generated by a HARDCODED `draws > 180` count threshold at Engine9 ~41405 — not by any
 * measured time. That verdict sent two investigations at the render path by mistake. FPS.md §1
 * is explicit: "draws are not the bottleneck. Don't chase it."
 * ⛔ SUPERSEDED 2026-09-21 by Mark ("read onibaba sensors let them tell you what fucked up exactly"): that FPS.md
 * line was wrong once draws left the ~250 band. At 1232 draws the CPU submit alone (9-11ms) overran the vsync
 * slot; the "unaccounted" time this probe hunts was vsync WAIT, not logic. Read the draw count FIRST. See FPS.md §1.
 *
 * WHAT THIS MEASURES: absolute fps is NOT headless-measurable (Chromium throttles offscreen
 * RAF — see probe-fps.js / probe-fps-oscillation.js). But this probe does not need fps. The
 * engine already instruments WORK-PER-TICK as EMAs on window:
 *
 *     _avgAiTime        total tickMonsterAI + v2 tick   (Engine9 ~41368)
 *     _avgPathfindTime  A* only                          (~27336)
 *     _avgCollisionTime pairwise monster collision       (~27334)
 *     _avgSensoryTime   LOS / perception                 (~27335)
 *     _avgPhysTime      physics                          (~41369)
 *     _avgRenderTime    full render path                 (~41370)
 *     _avgPrimaryRenderTime / _avgPipPassTime            (~41371 / ~19157)
 *
 * Milliseconds-of-work-per-tick is independent of how often ticks happen, so these stay valid
 * under headless RAF throttling. That is the whole trick.
 *
 * IT ALSO TRACKS DRIFT. Mark's log did not oscillate around a mean — it DECAYED (58,60 → 34,33
 * across the window). A monotonic session decay is the fingerprint of the documented PIP
 * ImageBitmap transfer leak (92→40→20, fixed 50f268e). So this probe compares the FIRST third
 * of the window against the LAST third for every series: a subsystem whose per-tick cost GROWS
 * is a leak; a flat profile alongside real-world decay points at GPU-side surfaces (which this
 * cannot see) rather than CPU.
 *
 * NOT A GATE. Reports only, never prescribes, and NEVER recommends throttling (FPS.md §0/§4).
 * Absolute fps remains Mark's hardware call.
 *
 *   SAMPLE_MS=60000 node scripts/probe-cpu-attribution.js
 */
const path = require('path');
const fs = require('fs');
const http = require('http');
const { chromium } = require('playwright');

const ROOT = path.resolve(__dirname, '..');
const ENTRY = process.env.SMOKE_ENTRY || 'OrigamiUnderworld.html';
const WARMUP_MS = parseInt(process.env.WARMUP_MS || '8000', 10);
const SAMPLE_MS = parseInt(process.env.SAMPLE_MS || '45000', 10);
const STEP_MS = parseInt(process.env.STEP_MS || '500', 10);

const MIME = {
    '.html': 'text/html; charset=utf-8', '.js': 'application/javascript; charset=utf-8',
    '.mjs':'application/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.css': 'text/css; charset=utf-8',
    '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml',
    '.ogg': 'audio/ogg', '.mp3': 'audio/mpeg', '.glb': 'model/gltf-binary', '.webp': 'image/webp',
};
function startServer() {
    return new Promise(res => {
        const srv = http.createServer((req, rs) => {
            const u = decodeURIComponent(req.url.split('?')[0]);
            const f = path.join(ROOT, u === '/' ? '/' + ENTRY : u);
            if (!f.startsWith(ROOT)) { rs.statusCode = 403; return rs.end(); }
            fs.readFile(f, (err, data) => {
                if (err) { rs.statusCode = 404; return rs.end(err.code); }
                rs.setHeader('Content-Type', MIME[path.extname(f).toLowerCase()] || 'application/octet-stream');
                rs.setHeader('Access-Control-Allow-Origin', '*');
                rs.end(data);
            });
        });
        srv.listen(0, '127.0.0.1', () => res(srv));
    });
}

const mean = xs => xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0;
// First-third vs last-third mean. Catches a per-tick cost that GROWS over a session (leak)
// as opposed to one that is merely expensive but flat.
function drift(series) {
    const xs = series.filter(n => typeof n === 'number' && !isNaN(n));
    if (xs.length < 6) return { n: xs.length, avg: 0, first: 0, last: 0, growth: 0, usable: false };
    const k = Math.floor(xs.length / 3);
    const first = mean(xs.slice(0, k)), last = mean(xs.slice(-k));
    return {
        n: xs.length,
        avg: +mean(xs).toFixed(3),
        first: +first.toFixed(3),
        last: +last.toFixed(3),
        growth: +(last - first).toFixed(3),
        max: +Math.max(...xs).toFixed(3),
        usable: true,
    };
}

const FIELDS = [
    ['_avgAiTime', 'AI total (tickMonsterAI + v2)'],
    ['_avgPathfindTime', '  └ A* pathfind'],
    ['_avgCollisionTime', '  └ monster collision'],
    ['_avgSensoryTime', '  └ sensory / LOS'],
    ['_avgPhysTime', 'physics'],
    ['_avgRenderTime', 'render path (total)'],
    ['_avgPrimaryRenderTime', '  └ primary'],
    ['_avgPipPassTime', '  └ PiP pass'],
];

(async () => {
    const server = await startServer();
    const port = server.address().port;
    const browser = await chromium.launch({
        args: ['--no-sandbox', '--disable-renderer-backgrounding',
               '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows',
               '--disable-features=CalculateNativeWinOcclusion'],
    });
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(`[top] ${e.message}`));
    page.on('console', m => { if (m.type() === 'error') errors.push(`[console.error] ${m.text().slice(0, 200)}`); });

    await page.goto(`http://127.0.0.1:${port}/${ENTRY}`, { waitUntil: 'domcontentloaded' });
    await page.waitForFunction(() => window.__engineReady === true, null, { timeout: 60000 });
    await page.bringToFront();
    console.log(`[probe-cpu] engine ready — warming ${WARMUP_MS}ms, then sampling ${SAMPLE_MS}ms @ ${STEP_MS}ms`);
    await page.waitForTimeout(WARMUP_MS);

    // Engine8.html → Engine9.html rename (2026-07-03) silently killed probe-fps-oscillation.js.
    // Match both arms so a rename degrades gracefully instead of exiting 2.
    // 2026-09-19 rename → Origami.RealityEngine.9.html (9239d996) — matched by the same regex arm below.
    const eng = page.frames().find(f => /(Engine[89]|RealityEngine\.9)\.html/.test(f.url()));
    if (!eng) { console.error('[probe-cpu] FAIL — engine iframe not found'); await browser.close(); process.exit(2); }

    // Label the rasterizer so drift numbers are never compared across different renderers.
    const renderer = await eng.evaluate(() => {
        try {
            const c = document.createElement('canvas');
            const gl = c.getContext('webgl2') || c.getContext('webgl');
            if (!gl) return 'NONE (WebGL context creation failed)';
            const ext = gl.getExtension('WEBGL_debug_renderer_info');
            const str = ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER);
            return (/swiftshader|software|llvmpipe/i.test(str || '') ? 'SOFTWARE · ' : 'HARDWARE · ') + str;
        } catch (e) { return 'NONE (probe error: ' + e.message + ')'; }
    });
    console.log(`[probe-cpu] renderer=${renderer}`);

    const series = {}; FIELDS.forEach(([k]) => series[k] = []);
    const heap = [], mons = [], aiTicks = [], drains = [];

    const tEnd = Date.now() + SAMPLE_MS;
    while (Date.now() < tEnd) {
        const r = await eng.evaluate(() => {
            const g = k => (typeof window[k] === 'number' ? window[k] : null);
            return {
                vals: {
                    _avgAiTime: g('_avgAiTime'), _avgPathfindTime: g('_avgPathfindTime'),
                    _avgCollisionTime: g('_avgCollisionTime'), _avgSensoryTime: g('_avgSensoryTime'),
                    _avgPhysTime: g('_avgPhysTime'), _avgRenderTime: g('_avgRenderTime'),
                    _avgPrimaryRenderTime: g('_avgPrimaryRenderTime'), _avgPipPassTime: g('_avgPipPassTime'),
                },
                heap: performance.memory ? performance.memory.usedJSHeapSize / 1048576 : null,
                mons: (typeof monsterWrappers !== 'undefined' && monsterWrappers) ? monsterWrappers.length : null,
                aiTicks: g('_aiV2Ticks'),
                drainDone: g('_lazyDrainDone'), drainTotal: g('_lazyDrainTotal'),
                // WHY-NOT-READABLE (2026-07-20). This probe reported "(not readable)" and
                // "accounted work/tick: 0.00ms" for EVERY subsystem while a direct read of the same
                // globals returned _avgRenderTime 4.91 / _avgPrimaryRenderTime 4.27 / _avgAiTime 0.13.
                // A blank instrument is WORSE than no instrument: Oni-Baba's FPS protest tells the
                // reader to "Run: npm run probe:cpu", and a blank result reinforces the false story
                // that the frame time is unmeasurable "GC/stall". Report the raw typeof so a missing
                // series names its own cause instead of vanishing behind a catch.
                _types: ['_avgAiTime','_avgPhysTime','_avgRenderTime','_avgPrimaryRenderTime','_avgPipPassTime']
                          .map(k => k + '=' + (typeof window[k]) + (typeof window[k] === 'number' ? '' : '(' + String(window[k]) + ')')).join(' '),
                _paused: !!window._softPaused + '/' + !!window._gamePaused + '/' + !!window._pauseOnInaction,
            };
        }).catch(e => ({ __err: String(e && e.message || e).slice(0, 200) }));
        if (r && r.__err) { if (!global.__probeErrShown) { global.__probeErrShown = 1; console.log('  [probe-cpu] ⚠ sample evaluate THREW: ' + r.__err); } continue; }
        if (r) {
            if (r._types && !global.__probeTypesShown) { global.__probeTypesShown = 1; console.log('  [probe-cpu] first sample typeof: ' + r._types + ' · paused(soft/game/onInaction)=' + r._paused); }
            for (const [k] of FIELDS) if (r.vals[k] != null) series[k].push(r.vals[k]);
            if (r.heap != null) heap.push(r.heap);
            if (r.mons != null) mons.push(r.mons);
            if (r.aiTicks != null) aiTicks.push(r.aiTicks);
            if (r.drainDone != null) drains.push(`${r.drainDone}/${r.drainTotal}`);
        }
        await page.waitForTimeout(STEP_MS);
    }

    await browser.close();
    await new Promise(r => server.close(r));

    console.log('\n[probe-cpu] MAIN-LOOP CPU ATTRIBUTION  (ms of work per tick — headless-valid)');
    console.log('  ' + 'subsystem'.padEnd(32) + 'avg'.padStart(8) + 'first⅓'.padStart(9) + 'last⅓'.padStart(9) + 'drift'.padStart(9) + 'max'.padStart(9));
    console.log('  ' + '-'.repeat(76));
    const results = {};
    for (const [k, label] of FIELDS) {
        const d = drift(series[k]);
        results[k] = d;
        if (!d.usable) { console.log('  ' + label.padEnd(32) + '   (not readable)'); continue; }
        const flag = d.growth > 0.5 ? '  ⚠ GROWING' : '';
        console.log('  ' + label.padEnd(32)
            + String(d.avg).padStart(8) + String(d.first).padStart(9) + String(d.last).padStart(9)
            + String(d.growth).padStart(9) + String(d.max).padStart(9) + flag);
    }

    const ai = results._avgAiTime, render = results._avgRenderTime;
    const accounted = (ai?.avg || 0) + (render?.avg || 0) + (results._avgPhysTime?.avg || 0);
    console.log('\n  accounted work/tick : ' + accounted.toFixed(2) + 'ms  (ai + render + phys)');
    console.log('  120fps budget       : 8.33ms/frame · 60fps budget: 16.67ms/frame');

    const hd = drift(heap);
    if (hd.usable) {
        console.log(`\n  JS heap             : ${hd.first.toFixed(1)} → ${hd.last.toFixed(1)} MB  (drift ${hd.growth > 0 ? '+' : ''}${hd.growth.toFixed(1)} MB)`
            + (hd.growth > 25 ? '  ⚠ GROWING' : ''));
    }
    if (mons.length) console.log(`  monsterWrappers     : ${mons[0]} → ${mons[mons.length - 1]}`);
    if (drains.length) console.log(`  lazy GLB drain      : ${drains[0]} → ${drains[drains.length - 1]}`);
    if (errors.length) { console.log(`\n  ⚠ ${errors.length} console/page error(s):`); errors.slice(0, 5).forEach(e => console.log('    ' + e)); }

    // READ-ONLY interpretation. Never prescribes a throttle (FPS.md §0/§4).
    console.log('\n[probe-cpu] READ:');
    const growers = FIELDS.filter(([k]) => results[k]?.usable && results[k].growth > 0.5);
    const renderGrows = (render?.growth || 0) > 0.5;
    const cpuGrowers = growers.filter(([k]) => !k.includes('Render') && k !== '_avgPipPassTime');
    const heapFlat = hd.usable && hd.growth < 15;

    if (cpuGrowers.length) {
        console.log('  ⚠ CPU per-tick cost GROWS in: ' + cpuGrowers.map(([, l]) => l.trim()).join(', '));
        console.log('    A growing CPU cost with a growing heap = accumulating JS state. Chase the allocation.');
    }
    if (renderGrows && heapFlat) {
        // The important discrimination this probe exists to make. Render time climbing while the JS heap
        // stays flat cannot be a JS leak — nothing is accumulating on the CPU side. It is GPU surfaces
        // (textures / framebuffers / transferred ImageBitmaps) piling up in driver memory, which slows
        // EVERY pass, primary included. That is the documented PIP ImageBitmap trap (fixed once in
        // 50f268e): bitmaps must close() on EVERY receiver path or surfaces leak ~60/s.
        console.log('  ⚠ RENDER time GROWS while the JS heap is FLAT'
            + ` (${render.first}ms → ${render.last}ms, heap ${hd.growth >= 0 ? '+' : ''}${hd.growth.toFixed(1)}MB).`);
        console.log('    This is NOT a CPU leak — flat heap means nothing is accumulating in JS.');
        console.log('    It is GPU-side surface accumulation (textures/FBOs/ImageBitmaps), which slows every');
        console.log('    pass incl. primary. Prime suspect: the PIP ImageBitmap transfer leak (50f268e) —');
        console.log('    a transferred bitmap must close() on EVERY receiver path, early returns included.');
    }
    if (!growers.length) {
        console.log('  ✅ nothing grows over the window — per-tick work is FLAT (no leak reproduced here).');
    }
    if (ai?.usable && render?.usable && ai.avg > render.avg * 2) {
        console.log(`  → AI (${ai.avg}ms) dominates render (${render.avg}ms). The frame is CPU-bound in the AI tick,`);
        console.log('    NOT the raster path. Oni-Baba\'s draw-call verdict (hardcoded draws>180, Engine9 ~41405)');
        console.log('    is a COUNT threshold, not a measurement — do not chase it (FPS.md §1).');
    }

    console.log('\n[probe-cpu] LIMITS — read these before acting:');
    console.log('  • Headless Chromium rasterises in SOFTWARE (SwiftShader). Absolute render ms here are');
    console.log('    NOT Mark\'s hardware numbers. The DRIFT is the signal; the magnitude is not.');
    console.log('  • A* / collision / sensory EMAs are written at the END of tickMonsterAI (α=0.1) and are');
    console.log('    FROZEN while window._softPaused or window._bossRevealActive — a soft combat pause holds');
    console.log('    them stale. They are also undefined until the first unpaused tick.');
    console.log('  • _avgPipPassTime refreshes only at PiP cadence (~4-20Hz) and freezes when _pipDisabled —');
    console.log('    a flat PiP row may mean "PiP off", not "PiP cheap".');
    if (mons.length && mons[mons.length - 1] === 0) {
        console.log('  • monsterWrappers = 0 for this whole run — headless never spawned any. So the AI/A*');
        console.log('    rows measure an EMPTY world and say NOTHING about a populated cabaret. Do not use');
        console.log('    this run to clear or convict the AI path; drive the player into a room with monsters.');
    }
    console.log('\n[probe-cpu] informational — absolute fps remains Mark\'s hardware gate.');
    process.exit(0);
})().catch(e => { console.error('[probe-cpu] harness error:', e); process.exit(2); });
